import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const pkgRoot = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const webDir = path.join(pkgRoot, "src", "locales", "web");
const outFile = path.join(pkgRoot, "src", "web-bundles.gen.ts");

const codes = fs
  .readdirSync(webDir)
  .filter((f) => f.endsWith(".json"))
  .map((f) => path.basename(f, ".json"))
  .sort();

if (codes.length === 0) {
  throw new Error(`No JSON locale files in ${webDir}`);
}

const lines = [
  "// Generated by scripts/gen-web-bundles.mjs — do not edit by hand.",
  "",
  ...codes.map((code) => `import ${code} from "./locales/web/${code}.json" with { type: "json" };`),
  "",
  "export const webBundles = {",
  ...codes.map((code) => `  ${code},`),
  "} as const;",
  "",
  "export type WebLocale = keyof typeof webBundles;",
  "",
  "export const WEB_LOCALES = Object.keys(webBundles) as WebLocale[];",
  "",
];

fs.writeFileSync(outFile, `${lines.join("\n")}\n`);
